<?php require "auth.php"; $msg="";if($_SERVER["REQUEST_METHOD"]==="POST"){$id=(int)$_POST["barang_id"];$j=(int)$_POST["jumlah"];$s=$conn->prepare("SELECT harga,stok FROM barang WHERE id=?");$s->bind_param("i",$id);$s->execute();$b=$s->get_result()->fetch_assoc();if($b&&$j>0&&$j<=$b["stok"]){$total=$b["harga"]*$j;$kode="TRX-".date("YmdHis");$conn->begin_transaction();try{$q=$conn->prepare("INSERT INTO transaksi(kode_transaksi,total) VALUES(?,?)");$q->bind_param("sd",$kode,$total);$q->execute();$tid=$conn->insert_id;$harga=$b["harga"];$d=$conn->prepare("INSERT INTO detail_transaksi(transaksi_id,barang_id,jumlah,harga,subtotal) VALUES(?,?,?,?,?)");$d->bind_param("iiidd",$tid,$id,$j,$harga,$total);$d->execute();$u=$conn->prepare("UPDATE barang SET stok=stok-? WHERE id=?");$u->bind_param("ii",$j,$id);$u->execute();$conn->commit();$msg="Transaksi berhasil: ".$kode;}catch(Throwable $e){$conn->rollback();$msg="Transaksi gagal.";}}else $msg="Barang tidak ada atau stok tidak cukup.";} $items=$conn->query("SELECT * FROM barang WHERE stok>0");$rows=$conn->query("SELECT * FROM transaksi ORDER BY id DESC");?><!doctype html><html lang="id"><head><meta charset="utf-8"><link rel="stylesheet" href="style.css"><title>Transaksi</title></head><body><header><b>Kantin POS</b><nav><a href="dashboard.php">Dashboard</a><a href="barang.php">Barang</a><a href="kategori.php">Kategori</a><a href="transaksi.php">Transaksi</a><a href="logout.php">Keluar</a></nav></header><main class="wide"><section class="panel"><h1>Transaksi</h1><p><?=$msg?></p><form method="post"><label>Barang</label><select name="barang_id" required><?php while($i=$items->fetch_assoc()):?><option value="<?=$i["id"]?>"><?=htmlspecialchars($i["nama_barang"])?> - Rp <?=number_format($i["harga"],0,",",".")?> (stok <?=$i["stok"]?>)</option><?php endwhile;?></select><label>Jumlah</label><input type="number" name="jumlah" min="1" value="1" required><button>Simpan Transaksi</button></form></section><section class="panel"><h2>Riwayat</h2><table><tr><th>Kode</th><th>Total</th><th>Tanggal</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?=htmlspecialchars($r["kode_transaksi"])?></td><td>Rp <?=number_format($r["total"],0,",",".")?></td><td><?=$r["created_at"]?></td></tr><?php endwhile;?></table></section></main></body></html>